fn startState(start: Start) u16 {
    return switch (start) {
        .@"program" => 0,
        .@"expr" => 1,
    };
}

fn startMarker(start: Start) u16 {
    return switch (start) {
        .@"program" => 143,
        .@"expr" => 145,
    };
}

